import { mkdir, writeFile } from 'node:fs/promises'
import { dirname, resolve } from 'node:path'
import {
  analyticsBannedPropertyKeys,
  officialEventAnalyticsEventNames,
} from '../dist/index.js'

const outPath = resolve(process.cwd(), '../../supabase/functions/_shared/analyticsRegistry.ts')

const content = `// Generated by packages/contracts/scripts/generate-deno-analytics.mjs.
// Do not edit manually. Run: npm run generate:deno-analytics -w @rally/contracts

export const officialEventAnalyticsEventNames = ${JSON.stringify(officialEventAnalyticsEventNames, null, 2)} as const

export type OfficialEventAnalyticsEventName = typeof officialEventAnalyticsEventNames[number]

export const analyticsBannedPropertyKeys = ${JSON.stringify(analyticsBannedPropertyKeys, null, 2)} as const

export type OfficialEventServerOutcome =
  | 'challenge_joined'
  | 'activity_submitted'
  | 'route_verified'
  | 'challenge_completed'
  | 'reward_claimed'
  | 'campaign_report_generated'

export type OfficialEventServerOutcomeProperties = {
  event_schema_version: 2
  source: 'server'
  surface:
    | 'campaign_hub'
    | 'challenge_detail'
    | 'run_active'
    | 'run_summary'
    | 'reward_claim'
    | 'admin_campaigns'
  campaign_id?: string
  campaign_slug?: string
  challenge_id?: string
  outcome: OfficialEventServerOutcome
  outcome_status: 'created' | 'already_exists' | 'completed' | 'failed'
}

export type OfficialEventServerOutcomeEvent = {
  name: 'server_outcome_recorded'
  properties: OfficialEventServerOutcomeProperties
}

export function assertNoBannedAnalyticsProperties(properties: Record<string, unknown>): void {
  for (const key of Object.keys(properties)) {
    if ((analyticsBannedPropertyKeys as readonly string[]).includes(key)) {
      throw new Error(\`banned_analytics_property:\${key}\`)
    }
  }
}

export function serverOutcomeRecorded(
  properties: OfficialEventServerOutcomeProperties,
): OfficialEventServerOutcomeEvent {
  assertNoBannedAnalyticsProperties(properties)
  return { name: 'server_outcome_recorded', properties }
}
`

await mkdir(dirname(outPath), { recursive: true })
await writeFile(outPath, content)
